--- a/src/triangle.cpp
+++ b/src/triangle.cpp
@@ -0,0 +1,25 @@
+#include "geometry/triangle.hpp"
+#include <cmath>
+#include <stdexcept>
+
+namespace geometry {
+
+Triangle::Triangle(double a, double b, double c) : a_(a), b_(b), c_(c) {
+    if (a <= 0 || b <= 0 || c <= 0) {
+        throw std::invalid_argument("Side lengths must be positive");
+    }
+    if (a + b <= c || a + c <= b || b + c <= a) {
+        throw std::invalid_argument("The given sides do not form a valid triangle");
+    }
+}
+
+std::string Triangle::name() const {
+    return "triangle";
+}
+
+double Triangle::area() const {
+    double s = (a_ + b_ + c_) / 2.0;
+    return std::sqrt(s * (s - a_) * (s - b_) * (s - c_));
+}
+
+}  // namespace geometry

