+Pose2D compose(const Pose2D& a, const Pose2D& b) {
+  Pose2D out;
+  double cos_a = std::cos(a.theta);
+  double sin_a = std::sin(a.theta);
+  out.x = a.x + cos_a * b.x - sin_a * b.y;
+  out.y = a.y + sin_a * b.x + cos_a * b.y;
+  out.theta = normalize_angle(a.theta + b.theta);
+  return out;
+}
+
 }  // namespace amr_utils

